17	export function Stylist() {
18	  const router = useRouter();
19	  const [status, setStatus] = useState<StylistStatus>("loading");
20	  const [occasion, setOccasion] = useState<UiOccasion>("everyday");
21	  const [formality, setFormality] = useState<number | null>(null);
22	  const [lean, setLean] = useState<string[]>([]);
23	  const [city, setCity] = useState<Chosen | null>(null);
24	  const [nonce, setNonce] = useState(0);
25	
26	  const [weather, setWeather] = useState<WeatherPayload | null>(null);
27	  const [looks, setLooks] = useState<Look[]>([]);
28	  const [selectedLook, setSelectedLook] = useState(0);
29	  const [cities, setCities] = useState<City[]>([]);
30	  const [refineOpen, setRefineOpen] = useState(false);
31	  const [missing, setMissing] = useState<string | null>(null);
32	  const [locating, setLocating] = useState(false);
33	  const [geoError, setGeoError] = useState<string | null>(null);
34	  // Optimistic: the row shows until we learn the browser has no geolocation at
35	  // all, at which point it disappears and city search is the only path.
36	  const [geoSupported, setGeoSupported] = useState(true);
37	
38	  // The silent refresh must never overwrite a location the user meant to keep.
39	  // Two ways that can happen, both guarded here:
40	  //   1. a RACE — the async permission→position chain resolving after the user
41	  //      has already picked a city in this session;
42	  //   2. a SAVED CITY — profiles.location_source === 'city' is a deliberate
43	  //      choice (decision L2), so GPS must not silently replace it.
44	  // The fix is parked in a ref until both gates are known, so geolocation still
45	  // starts immediately rather than waiting on the first generate to return.
46	  const userChoseRef = useRef(false);
47	  const pendingGeoRef = useRef<Chosen | null>(null);
48	  const geoAllowedRef = useRef<boolean | null>(null); // null = stored origin unknown yet
49	
50	  const applyPendingGeo = useCallback(() => {
51	    if (userChoseRef.current) return; // gate 1
52	    if (geoAllowedRef.current !== true) return; // gate 2
53	    const fix = pendingGeoRef.current;
54	    if (!fix) return;
55	    pendingGeoRef.current = null;
56	    setCity(fix);
57	  }, []);
58	
59	  useEffect(() => {
60	    let cancelled = false;
61	    permissionState().then((state) => {
62	      if (cancelled) return;
63	      if (state === "unsupported") {
64	        setGeoSupported(false);
65	        return;
66	      }
67	      if (state !== "granted") return; // querying never prompts; reading would
68	      getCurrentPosition()
69	        .then((c) => {
70	          if (cancelled) return;
71	          pendingGeoRef.current = { ...c, label: "Current location", source: "geo" };
72	          applyPendingGeo();
73	        })
74	        .catch(() => {
75	          /* silent path — never surface an error the user didn't ask for */
76	        });
77	    });
78	    return () => {
79	      cancelled = true;
80	    };
81	  }, [applyPendingGeo]);
82	
83	  // An explicit tap always wins, including over a saved city.
84	  const useMyLocation = useCallback(() => {
85	    userChoseRef.current = true;
86	    pendingGeoRef.current = null;
87	    setLocating(true);
88	    setGeoError(null);
89	    getCurrentPosition()
90	      .then((c) => setCity({ ...c, label: "Current location", source: "geo" }))
91	      .catch((e) =>
92	        setGeoError(e instanceof GeoError && e.kind === "denied" ? DENIED_COPY : FAILED_COPY),
93	      )
94	      .finally(() => setLocating(false));
95	  }, []);
96	
97	  const applyResult = useCallback(
98	    (res: GenerateResult) => {
99	      // The first result tells us the STORED provenance. A saved city blocks the
100	      // silent refresh for good; anything else releases the parked GPS fix.
101	      if (geoAllowedRef.current === null && res.status !== "error") {
102	        geoAllowedRef.current = res.weather.locationOrigin !== "city";
103	        applyPendingGeo();
104	      }
105	
106	      if (res.status === "ok") {
107	        setWeather(res.weather);
108	        setLooks(res.looks);
109	        setSelectedLook(0);
110	        setStatus("ok");
111	      } else if (res.status === "empty") {
112	        setWeather(res.weather);
113	        setLooks([]);
114	        setMissing(res.missing);
115	        setStatus("empty");
116	      } else {
117	        setStatus("error");
118	      }
119	
120	      // Persist only a location the user actually supplied — including the
121	      // silent refresh, which is the point of keeping the record fresh. Never
122	      // for the profile/default fallback: there is nothing new to write.
123	      if (city && res.status !== "error") {
124	        saveLocation({ ...city, timezone: res.weather.timezone }).catch(() => {
125	          /* non-fatal — never disturb the looks */
126	        });
127	      }
128	    },
129	    [city, applyPendingGeo],
130	  );
131	
132	  // Reads today's stored set (Decision 5). Switching occasion runs this again,
133	  // but the action answers from the database — no AI call, no spend.
134	  useEffect(() => {
135	    let cancelled = false;
136	    setStatus("loading");
137	    generate({ occasion, formality, lean, city: city ?? undefined }).then((res) => {
138	      if (cancelled) return;
139	      applyResult(res);
140	    });
141	    return () => {
142	      cancelled = true;
143	    };
144	  }, [occasion, formality, lean, city, nonce, applyResult]);
145	
146	  /**
147	   * The only path that spends an AI call on a day already answered.
148	   *
149	   * Deliberately a direct call rather than an effect dependency: a flag routed
150	   * through the effect can still be in flight when the user switches occasion,
151	   * and would then regenerate that occasion too.
152	   */
153	  const regenerate = useCallback(() => {
154	    setStatus("loading");
155	    generate({ occasion, formality, lean, city: city ?? undefined, regenerate: true }).then(
156	      applyResult,
157	    );
158	  }, [occasion, formality, lean, city, applyResult]);
159	
160	  return (
161	    <StylistView
162	      status={status}
163	      weather={weather}
164	      looks={looks}
165	      selectedLook={selectedLook}
166	      occasion={occasion}
167	      cities={cities}
168	      refineOpen={refineOpen}
169	      missing={missing}
170	      locating={locating}
171	      geoError={geoError}
172	      onOccasion={setOccasion}
173	      onOpenRefine={() => setRefineOpen(true)}
174	      onCloseRefine={() => setRefineOpen(false)}
175	      onRefineApply={({ formality: f, lean: c }) => {
176	        setFormality(f);
177	        setLean(c);
178	        setRefineOpen(false);
179	      }}
180	      onCityChange={(c) => {
181	        userChoseRef.current = true;
182	        pendingGeoRef.current = null;
183	        setCity({ lat: c.lat, lon: c.lon, label: c.name, source: "city" });
184	      }}
185	      onCitySearch={(q) => {
186	        if (q.trim().length < 2) return;
187	        searchCities(q).then(setCities);
188	      }}
189	      onUseMyLocation={geoSupported ? useMyLocation : undefined}
190	      onSelectLook={setSelectedLook}
191	      onRetry={() => setNonce((n) => n + 1)}
192	      onRegenerate={regenerate}
193	      onOpenItem={(id) => router.push(`/closet/${id}`)}
194	    />
195	  );
196	}
