5	/** Today's stored set for one occasion, in the order the stylist chose. */
6	export async function loadDailyLooks(
7	  userId: string,
8	  occasion: string,
9	  generatedOn: string,
10	): Promise<StoredLook[] | null> {
11	  const supabase = await createClient();
12	  const { data } = await supabase
13	    .from("outfits")
14	    .select("look_name, ai_reasoning, layout, look_index")
15	    .eq("user_id", userId)
16	    .eq("occasion", occasion)
17	    .eq("generated_on", generatedOn)
18	    .order("look_index", { ascending: true });
19	
20	  if (!data || data.length === 0) return null;
21	
22	  return data.map((row) => {
23	    const layout = (row.layout ?? {}) as {
24	      anchorIndex?: number;
25	      pieces?: StoredLook["pieces"];
26	    };
27	    return {
28	      lookName: row.look_name ?? "",
29	      why: row.ai_reasoning ?? "",
30	      anchorIndex: layout.anchorIndex ?? 0,
31	      pieces: layout.pieces ?? [],
32	    };
33	  });
34	}
