36	/**
37	 * Replace today's set for one occasion. Delete-then-insert rather than upsert:
38	 * a regenerate may return a different NUMBER of looks, and leftovers from the
39	 * previous set must not survive alongside the new one.
40	 */
41	export async function saveDailyLooks(
42	  userId: string,
43	  occasion: string,
44	  generatedOn: string,
45	  weather: WeatherPayload,
46	  looks: Look[],
47	): Promise<void> {
48	  const supabase = await createClient();
49	
50	  await supabase
51	    .from("outfits")
52	    .delete()
53	    .eq("user_id", userId)
54	    .eq("occasion", occasion)
55	    .eq("generated_on", generatedOn);
56	
57	  const rows = looks.map((look, i) => ({
58	    user_id: userId,
59	    occasion,
60	    generated_on: generatedOn,
61	    look_index: i,
62	    look_name: look.name,
63	    ai_reasoning: look.why,
64	    weather_snapshot: weather,
65	    layout: {
66	      anchorIndex: look.anchorIndex,
67	      pieces: look.pieces.map((p) => ({ itemId: p.itemId, slot: p.slot })),
68	    },
69	  }));
70	
71	  const { data: inserted } = await supabase
72	    .from("outfits")
73	    .insert(rows)
74	    .select("id, look_index");
75	  if (!inserted) return;
76	
77	  // outfit_items is the relational record — it is what wear_logs and future
78	  // analytics join against. The renderable geometry lives in outfits.layout.
79	  const links = inserted.flatMap((row) => {
80	    const look = looks[row.look_index];
81	    return (look?.pieces ?? []).map((p) => ({
82	      outfit_id: row.id,
83	      item_id: p.itemId,
84	      slot: p.category,
85	    }));
86	  });
87	  if (links.length) await supabase.from("outfit_items").insert(links);
88	}
